  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_hs_math_review_item_time` (`item_id`,`reviewed_at`),
  KEY `idx_hs_math_review_item_status` (`item_id`,`review_status`,`reviewed_at`),
