) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='人工审核历史；passed≠items.status=approved；题目删除默认 RESTRICT 防误删';
